from math import ceil, erfc, sqrt

def two_prop_z(x1, n1, x2, n2):
    p1, p2 = x1 / n1, x2 / n2
    p = (x1 + x2) / (n1 + n2)
    se = sqrt(p * (1 - p) * (1 / n1 + 1 / n2))
    z = (p2 - p1) / se
    pval = erfc(abs(z) / sqrt(2))
    se_d = sqrt(p1 * (1 - p1) / n1 + p2 * (1 - p2) / n2)
    ci = (p2 - p1 - 1.96 * se_d, p2 - p1 + 1.96 * se_d)
    return z, pval, ci

def sample_size(p, delta, za=1.96, zb=0.84):
    var = p * (1 - p) + (p + delta) * (1 - p - delta)
    return ceil((za + zb) ** 2 * var / delta ** 2)

import numpy as np

def relu(x):
    return np.maximum(0, x)

def sigmoid(x):
    return 1 / (1 + np.exp(-x))

def gelu(x):
    c = np.sqrt(2 / np.pi)
    return 0.5 * x * (1 + np.tanh(c * (x + 0.044715 * x**3)))

def d_relu(x):
    return (x > 0).astype(float)

def d_sigmoid(x):
    s = sigmoid(x)
    return s * (1 - s)

def d_tanh(x):
    return 1 - np.tanh(x) ** 2

import numpy as np

def stump(X, y, w):
    best = (np.inf, 0, 0.0, 1)
    for j in range(X.shape[1]):
        for t in np.unique(X[:, j])[:-1]:
            for s in (1, -1):
                p = np.where(X[:, j] <= t, s, -s)
                e = w[p != y].sum()
                if e < best[0]:
                    best = (e, j, t, s)
    return best

def adaboost(X, y, T=20):
    w = np.full(len(y), 1 / len(y))
    model = []
    for _ in range(T):
        e, j, t, s = stump(X, y, w)
        a = 0.5 * np.log((1 - e) / max(e, 1e-12))
        p = np.where(X[:, j] <= t, s, -s)
        w = w * np.exp(-a * y * p)
        w /= w.sum()
        model.append((a, j, t, s))
    return model

def predict(model, X):
    f = np.zeros(len(X))
    for a, j, t, s in model:
        f += a * np.where(X[:, j] <= t, s, -s)
    return np.sign(f)

import numpy as np

def init_state(w):
    return {"m": np.zeros_like(w), "v": np.zeros_like(w), "t": 0}

def adam_step(w, g, st, lr=1e-3, b1=0.9, b2=0.999, eps=1e-8):
    st["t"] += 1
    st["m"] = b1 * st["m"] + (1 - b1) * g
    st["v"] = b2 * st["v"] + (1 - b2) * g * g
    m_hat = st["m"] / (1 - b1 ** st["t"])
    v_hat = st["v"] / (1 - b2 ** st["t"])
    return w - lr * m_hat / (np.sqrt(v_hat) + eps)

import numpy as np

def init_state(w):
    return {"m": np.zeros_like(w), "v": np.zeros_like(w), "t": 0}

def _adam_dir(st, g, b1, b2, eps):
    st["t"] += 1
    st["m"] = b1 * st["m"] + (1 - b1) * g
    st["v"] = b2 * st["v"] + (1 - b2) * g * g
    m_hat = st["m"] / (1 - b1 ** st["t"])
    v_hat = st["v"] / (1 - b2 ** st["t"])
    return m_hat / (np.sqrt(v_hat) + eps)

def adam_l2_step(st, w, g, lr=1e-3, b1=0.9, b2=0.999,
                 eps=1e-8, wd=0.0):
    d = _adam_dir(st, g + wd * w, b1, b2, eps)
    return w - lr * d

def adamw_step(st, w, g, lr=1e-3, b1=0.9, b2=0.999,
               eps=1e-8, wd=0.0):
    d = _adam_dir(st, g, b1, b2, eps)
    return w - lr * (d + wd * w)

import numpy as np

def adapter_forward(x, Wd, bd, Wu, bu):
    h = np.maximum(x @ Wd + bd, 0)
    return x + h @ Wu + bu

def param_count(d, r):
    return 2 * d * r + r + d

def lora_forward(x, W, A, B, alpha):
    s = alpha / A.shape[0]
    return x @ W.T + s * (x @ A.T) @ B.T

import numpy as np

def dist2(A, B):
    return (A**2).sum(1)[:, None] - 2 * A @ B.T + (B**2).sum(1)

def kmeans(X, k, seed=0, iters=20):
    rng = np.random.default_rng(seed)
    C = X[rng.choice(len(X), k, replace=False)].copy()
    for _ in range(iters):
        a = dist2(X, C).argmin(1)
        for j in range(k):
            if (a == j).any():
                C[j] = X[a == j].mean(0)
    return C

def build_ivf(X, nlist, seed=0):
    C = kmeans(X, nlist, seed)
    a = dist2(X, C).argmin(1)
    cells = [np.where(a == j)[0] for j in range(nlist)]
    return {"X": X, "C": C, "cells": cells}

def search_ivf(index, q, k, nprobe):
    dc = ((index["C"] - q) ** 2).sum(1)
    probe = np.argsort(dc)[:nprobe]
    ids = np.concatenate([index["cells"][j] for j in probe])
    d = ((index["X"][ids] - q) ** 2).sum(1)
    order = np.argsort(d, kind="stable")[:k]
    return ids[order], len(index["C"]) + len(ids)

def recall_at_k(approx_ids, exact_ids):
    return len(set(approx_ids) & set(exact_ids)) / len(exact_ids)

import numpy as np

def generate(next_logits, prompt, max_new, eos):
    tokens = list(prompt)
    for _ in range(max_new):
        z = next_logits(tokens)
        t = int(np.argmax(z))
        tokens.append(t)
        if t == eos:
            break
    return tokens

def uncached(emb, W):
    def f(tokens):
        return emb[tokens].mean(axis=0) @ W
    return f

def cached(emb, W):
    st = {"n": 0, "sum": np.zeros(emb.shape[1])}
    def f(tokens):
        new = tokens[st["n"]:]      # prefill: all, decode: one
        st["sum"] = st["sum"] + emb[new].sum(axis=0)
        st["n"] = len(tokens)
        return st["sum"] / len(tokens) @ W
    return f

import numpy as np

def vocab_of(docs, extra=()):
    return sorted({w for d in docs for w in d.split()} | set(extra))

def bow(docs, vocab):
    idx = {w: i for i, w in enumerate(vocab)}
    X = np.zeros((len(docs), len(vocab)))
    for r, d in enumerate(docs):
        for w in d.split():
            X[r, idx[w]] += 1
    return X

def pad(s):
    return ["<s>"] + s.split() + ["</s>"]

def bigram_counts(sents, vocab):
    idx = {w: i for i, w in enumerate(vocab)}
    C = np.zeros((len(vocab), len(vocab)))
    for s in sents:
        t = pad(s)
        for a, b in zip(t[:-1], t[1:]):
            C[idx[a], idx[b]] += 1
    return C

def bigram_prob(C, k=1.0):
    V = C.shape[0]
    return (C + k) / (C.sum(axis=1, keepdims=True) + k * V)

def sentence_logprob(sent, P, vocab):
    idx = {w: i for i, w in enumerate(vocab)}
    t = pad(sent)
    return sum(np.log(P[idx[a], idx[b]])
               for a, b in zip(t[:-1], t[1:]))

import numpy as np

def softmax(s):
    e = np.exp(s - s.max())
    return e / e.sum()

def additive_attention(s, H, Ws, Wh, v):
    # s: decoder state (ds,), H: encoder states (T, dh)
    e = np.tanh(s @ Ws + H @ Wh) @ v      # (T,) scores
    a = softmax(e)
    return a @ H, a

import numpy as np

def posterior(prior, lik):
    joint = np.asarray(prior) * np.asarray(lik)
    return joint / joint.sum()

def update(prior, lik_rows):
    post = np.asarray(prior, dtype=float)
    for lik in lik_rows:
        post = posterior(post, lik)
    return post

import numpy as np

def beam_search(step, bos, L, B):
    beams = [([bos], 0.0)]
    for _ in range(L):
        cand = []
        for seq, sc in beams:
            lp = step(seq)
            for t in range(len(lp)):
                cand.append((seq + [t], sc + lp[t]))
        cand.sort(key=lambda c: -c[1])
        beams = cand[:B]
    return beams

import numpy as np

def ngram_set(tokens, n):
    return {tuple(tokens[i:i + n])
            for i in range(len(tokens) - n + 1)}

def contamination_rate(train_docs, bench_items, n=13):
    seen = set()
    for doc in train_docs:
        seen |= ngram_set(doc, n)
    flags = [bool(ngram_set(it, n) & seen) for it in bench_items]
    return float(np.mean(flags)), flags

def memorisation_ratio(loss_fn, item, perturbations):
    base = np.mean([loss_fn(p) for p in perturbations])
    return loss_fn(item) / base

def accuracy_gap(correct, contaminated):
    c = np.asarray(correct, float)
    m = np.asarray(contaminated, bool)
    return c[m].mean() - c[~m].mean()

import numpy as np

def rnn_pass(X, Wx, Wh, b):
    h = np.zeros(Wh.shape[0])
    states = []
    for x in X:
        h = np.tanh(x @ Wx + h @ Wh + b)
        states.append(h)
    return np.array(states)

def bi_rnn(X, fwd, bwd):
    hf = rnn_pass(X, *fwd)
    hb = rnn_pass(X[::-1], *bwd)[::-1]
    return np.concatenate([hf, hb], axis=1)

import numpy as np

def fit_loglog_slope(ns, costs):
    return float(np.polyfit(np.log(ns), np.log(costs), 1)[0])

def linear_search(a, x):
    ops = 0
    for i, v in enumerate(a):
        ops += 1
        if v == x:
            return i, ops
    return -1, ops

def binary_search(a, x):
    lo, hi, ops = 0, len(a), 0
    while lo < hi:
        mid = (lo + hi) // 2
        ops += 1
        if a[mid] < x:
            lo = mid + 1
        else:
            hi = mid
    found = lo < len(a) and a[lo] == x
    return (lo if found else -1), ops

def insertion_sort(a):
    a, ops = list(a), 0
    for i in range(1, len(a)):
        j = i
        while j > 0:
            ops += 1
            if a[j - 1] <= a[j]:
                break
            a[j - 1], a[j] = a[j], a[j - 1]
            j -= 1
    return a, ops

def merge_sort(a):
    if len(a) <= 1:
        return list(a), 0
    m = len(a) // 2
    L, cl = merge_sort(a[:m])
    R, cr = merge_sort(a[m:])
    out, i, j, ops = [], 0, 0, cl + cr
    while i < len(L) and j < len(R):
        ops += 1
        if L[i] <= R[j]:
            out.append(L[i]); i += 1
        else:
            out.append(R[j]); j += 1
    return out + L[i:] + R[j:], ops

import numpy as np
from collections import Counter

def ngrams(t, n):
    return Counter(tuple(t[i:i + n]) for i in range(len(t) - n + 1))

def corpus_bleu(hyps, refs, max_n=4):
    match, total = np.zeros(max_n), np.zeros(max_n)
    hl = rl = 0
    for h, r in zip(hyps, refs):
        hl, rl = hl + len(h), rl + len(r)
        for n in range(1, max_n + 1):
            hn, rn = ngrams(h, n), ngrams(r, n)
            match[n - 1] += sum(min(c, rn[g]) for g, c in hn.items())
            total[n - 1] += max(len(h) - n + 1, 0)
    if match.min() == 0:
        return 0.0
    bp = 1.0 if hl > rl else np.exp(1 - rl / hl)
    return 100 * bp * np.exp(np.log(match / total).mean())

from collections import Counter

def merge(s, a, b):
    out, i = [], 0
    while i < len(s):
        if i < len(s) - 1 and (s[i], s[i + 1]) == (a, b):
            out.append(a + b)
            i += 2
        else:
            out.append(s[i])
            i += 1
    return out

def bpe_train(words, k):
    seqs, merges = [list(w) for w in words], []
    for _ in range(k):
        cnt = Counter()
        for s in seqs:
            cnt.update(zip(s, s[1:]))
        if not cnt:
            break
        a, b = min(cnt, key=lambda p: (-cnt[p], p))
        seqs = [merge(s, a, b) for s in seqs]
        merges.append((a, b))
    return merges

def bpe_encode(word, merges):
    s = list(word)
    for a, b in merges:
        s = merge(s, a, b)
    return s

import re
from math import comb
from collections import Counter

def extract_final_answer(text):
    pat = r"answer\s*:\s*\$?\s*(-?[\d,]*\.?\d+|[^\s.,;]+)"
    m = re.findall(pat, text, re.I)
    return m[-1].replace(",", "").lower() if m else None

def majority_vote(answers):
    votes = Counter(a for a in answers if a is not None)
    if not votes:
        return None
    return votes.most_common(1)[0][0]

def majority_accuracy(p, n):
    # P(more than half of n independent votes are correct), odd n
    return sum(comb(n, k) * p**k * (1 - p)**(n - k)
               for k in range(n // 2 + 1, n + 1))

import numpy as np

def balanced_weights(y):
    classes, counts = np.unique(y, return_counts=True)
    return dict(zip(classes, len(y) / (len(classes) * counts)))

def weighted_logloss(y, p, w):
    sw = np.array([w[c] for c in y])
    ll = -(y * np.log(p) + (1 - y) * np.log(1 - p))
    return (sw * ll).sum() / sw.sum()

def oversample(X, y, rng):
    classes, counts = np.unique(y, return_counts=True)
    idx = []
    for c, n in zip(classes, counts):
        pool = np.flatnonzero(y == c)
        extra = rng.choice(pool, counts.max() - n, replace=True)
        idx.append(np.r_[pool, extra])
    idx = np.concatenate(idx)
    return X[idx], y[idx]

import numpy as np

def psi(ref, cur, bins=10, eps=1e-4):
    edges = np.quantile(ref, np.linspace(0, 1, bins + 1))
    edges[0], edges[-1] = -np.inf, np.inf
    a = np.histogram(ref, edges)[0] / len(ref)
    b = np.histogram(cur, edges)[0] / len(cur)
    a, b = np.clip(a, eps, None), np.clip(b, eps, None)
    return ((b - a) * np.log(b / a)).sum()

def ks_stat(a, b):
    grid = np.sort(np.r_[a, b])
    Fa = np.searchsorted(np.sort(a), grid, side="right") / len(a)
    Fb = np.searchsorted(np.sort(b), grid, side="right") / len(b)
    return np.abs(Fa - Fb).max()

def pack_chunks(chunks, budget):
    order = sorted(chunks, key=lambda c: -c[2] / c[1])
    kept, used = [], 0
    for name, tok, score in order:
        if used + tok <= budget:
            kept.append(name)
            used += tok
    return kept, used

def truncate_history(turns, budget):
    kept, used = [], 0
    for role, tok in reversed(turns):
        if used + tok > budget:
            break
        kept.append((role, tok))
        used += tok
    return kept[::-1], used

def order_for_attention(chunks):
    ranked = sorted(chunks, key=lambda c: -c[2])
    front, back = ranked[0::2], ranked[1::2]
    return front + back[::-1]

def build_context(window, system, reserve, history, chunks,
                  share=0.4):
    avail = window - reserve - system
    kept_h, used_h = truncate_history(history, int(share * avail))
    names, used_c = pack_chunks(chunks, avail - used_h)
    total = system + used_h + used_c
    return dict(system=system, history=used_h, docs=used_c,
                reserve=reserve, total_in=total,
                slack=window - reserve - total, chunks=names)

import numpy as np

def softmax(s):
    e = np.exp(s - s.max(axis=-1, keepdims=True))
    return e / e.sum(axis=-1, keepdims=True)

def static_embed(ids, E):
    return E[ids]

def self_attention(X, W):
    Q, K, V = X @ W["q"], X @ W["k"], X @ W["v"]
    A = softmax(Q @ K.T / np.sqrt(K.shape[1]))
    return A @ V, A

import math

def simulate_static(lengths, batch_size):
    steps = 0
    for i in range(0, len(lengths), batch_size):
        steps += max(lengths[i:i + batch_size])
    return steps, sum(lengths) / (steps * batch_size)

def simulate_continuous(lengths, batch_size):
    queue, active, steps = list(lengths)[::-1], [], 0
    while queue or active:
        while queue and len(active) < batch_size:
            active.append(queue.pop())
        active = [r - 1 for r in active]
        active = [r for r in active if r > 0]
        steps += 1
    return steps, sum(lengths) / (steps * batch_size)

def blocks_needed(tokens, block_size):
    blocks = math.ceil(tokens / block_size)
    return blocks, blocks * block_size - tokens

import numpy as np

def is_convex_quadratic(Q, tol=1e-10):
    return bool(np.linalg.eigvalsh((Q + Q.T) / 2).min() >= -tol)

def solve_eq_qp(Q, c, A, b):
    n, m = len(c), len(b)
    K = np.block([[Q, A.T], [A, np.zeros((m, m))]])
    sol = np.linalg.solve(K, np.concatenate([-c, b]))
    return sol[:n], sol[n:]

def kkt_residuals(Q, c, A, b, x, lam):
    stationarity = Q @ x + c + A.T @ lam
    feasibility = A @ x - b
    return (np.linalg.norm(stationarity),
            np.linalg.norm(feasibility))

import numpy as np

def kfold_indices(n, k, seed=0):
    idx = np.random.RandomState(seed).permutation(n)
    folds = np.array_split(idx, k)
    for i in range(k):
        train = np.concatenate(folds[:i] + folds[i + 1:])
        yield train, folds[i]

def cross_val_score(fit, score, X, y, k=5, seed=0):
    out = []
    for tr, va in kfold_indices(len(X), k, seed):
        model = fit(X[tr], y[tr])
        out.append(score(model, X[va], y[va]))
    return np.array(out)

import numpy as np

def fit_scaler(X):
    return X.mean(0), X.std(0)

def transform(X, stats):
    mu, sd = stats
    return (X - mu) / sd

def split_then_scale(X, n_train):
    stats = fit_scaler(X[:n_train])
    tr, te = X[:n_train], X[n_train:]
    return transform(tr, stats), transform(te, stats)

def leaky_scale(X, n_train):
    Z = transform(X, fit_scaler(X))
    return Z[:n_train], Z[n_train:]

import numpy as np

def dbscan(X, eps, min_pts):
    n = len(X)
    D = np.linalg.norm(X[:, None] - X[None], axis=2)
    nbrs = [np.flatnonzero(D[i] <= eps) for i in range(n)]
    core = np.array([len(nb) >= min_pts for nb in nbrs])
    labels = np.full(n, -1)
    c = 0
    for i in range(n):
        if labels[i] != -1 or not core[i]:
            continue
        labels[i] = c
        stack = [i]
        while stack:
            j = stack.pop()
            if not core[j]:
                continue
            for k in nbrs[j]:
                if labels[k] == -1:
                    labels[k] = c
                    stack.append(k)
        c += 1
    return labels

import numpy as np

def gini(y):
    p = np.bincount(y) / len(y)
    return 1 - p @ p

def grow(X, y, depth):
    best, leaf = (gini(y), None, None), np.bincount(y).argmax()
    if depth == 0 or best[0] == 0:
        return leaf
    for j in range(X.shape[1]):
        v = np.unique(X[:, j])
        for t in (v[:-1] + v[1:]) / 2:
            m = X[:, j] <= t
            s = m.mean() * gini(y[m]) + (1 - m.mean()) * gini(y[~m])
            if s < best[0] - 1e-12:
                best = (s, j, t)
    if best[1] is None:
        return leaf
    _, j, t = best
    m = X[:, j] <= t
    left = grow(X[m], y[m], depth - 1)
    return (j, t, left, grow(X[~m], y[~m], depth - 1))

def predict_one(tree, x):
    while isinstance(tree, tuple):
        j, t, left, right = tree
        tree = left if x[j] <= t else right
    return tree

import numpy as np

def f(x, W, b):
    return np.sum(np.tanh(W @ x + b) ** 2)

def analytic_grad(x, W, b):
    t = np.tanh(W @ x + b)
    return W.T @ (2 * t * (1 - t ** 2))

def numerical_grad(f, x, h=1e-5, kind="central"):
    g = np.zeros_like(x)
    for i in range(len(x)):
        e = np.zeros_like(x)
        e[i] = h
        if kind == "central":
            g[i] = (f(x + e) - f(x - e)) / (2 * h)
        else:
            g[i] = (f(x + e) - f(x)) / h
    return g

def rel_error(a, n):
    return np.linalg.norm(a - n) / (
        np.linalg.norm(a) + np.linalg.norm(n))

import numpy as np

def make_schedule(T, b0=1e-4, b1=0.02):
    betas = np.linspace(b0, b1, T)
    return betas, np.cumprod(1 - betas)

def q_sample(x0, t, abar, eps):
    return np.sqrt(abar[t]) * x0 + np.sqrt(1 - abar[t]) * eps

def q_step(x, t, betas, eps):
    return np.sqrt(1 - betas[t]) * x + np.sqrt(betas[t]) * eps

import math

def fixed_chunks(tokens, size, overlap):
    step = size - overlap
    stop = max(len(tokens) - overlap, 1)
    return [tokens[i:i + size] for i in range(0, stop, step)]

def chunk_count(n, size, overlap):
    if n <= size:
        return 1 if n else 0
    return math.ceil((n - overlap) / (size - overlap))

SEPS = ("\n\n", "\n", ". ", " ")

def recursive_split(text, max_len, separators=SEPS):
    if len(text) <= max_len:
        return [text]
    if not separators:
        return [text[i:i + max_len]
                for i in range(0, len(text), max_len)]
    sep, rest = separators[0], separators[1:]
    parts = text.split(sep)
    parts = [p + sep for p in parts[:-1]] + [parts[-1]]
    out, cur = [], ""
    for p in parts:
        if len(p) > max_len:
            if cur:
                out.append(cur)
                cur = ""
            out.extend(recursive_split(p, max_len, rest))
        elif len(cur) + len(p) <= max_len:
            cur += p
        else:
            out.append(cur)
            cur = p
    if cur:
        out.append(cur)
    return out

import re, unicodedata
from html.parser import HTMLParser

SKIP = {"script", "style", "title", "nav", "header", "footer",
        "aside"}
BLOCK = {"p", "div", "li", "br", "tr", "h1", "h2", "h3", "h4"}

class _Text(HTMLParser):
    def __init__(self):
        super().__init__()
        self.out, self.skip = [], 0
    def handle_starttag(self, tag, attrs):
        if tag in SKIP:
            self.skip += 1
        elif tag in BLOCK:
            self.out.append("\n\n")
    def handle_endtag(self, tag):
        if tag in SKIP:
            self.skip = max(0, self.skip - 1)
        elif tag in BLOCK:
            self.out.append("\n\n")
    def handle_data(self, data):
        if not self.skip:
            self.out.append(data)

def normalise_text(s):
    s = unicodedata.normalize("NFKC", s)
    s = re.sub(r"(\w)-\n(\w)", r"\1\2", s)
    s = re.sub(r"[ \t]+", " ", s)
    s = "\n".join(line.strip() for line in s.split("\n"))
    return re.sub(r"\n{3,}", "\n\n", s).strip()

def html_to_text(html):
    p = _Text()
    p.feed(html)
    return normalise_text("".join(p.out))

def drop_repeated_lines(pages, min_frac=0.6):
    def key(line):
        return re.sub(r"\d+", "#", line.strip())
    seen = {}
    for pg in pages:
        for k in {key(l) for l in pg.split("\n") if l.strip()}:
            seen[k] = seen.get(k, 0) + 1
    keep = lambda l: not l.strip() or (
        seen[key(l)] / len(pages) < min_frac)
    return ["\n".join(l for l in pg.split("\n") if keep(l))
            for pg in pages]

def attach_metadata(chunks, source, page, section=None):
    return [{"text": c, "source": source, "page": page,
             "section": section, "chunk": i}
            for i, c in enumerate(chunks)]

import numpy as np

def matmul_naive(A, B):
    m, k = A.shape
    n = B.shape[1]
    C = np.zeros((m, n))
    for i in range(m):
        for j in range(n):
            C[i, j] = sum(A[i, p] * B[p, j] for p in range(k))
    return C

def chain_cost(dims, order):
    # matrix i has shape dims[i] x dims[i+1]; order is nested
    # pairs of indices, e.g. ((0, 1), 2)
    def go(t):
        if isinstance(t, int):
            return dims[t], dims[t + 1], 0
        r1, c1, f1 = go(t[0])
        r2, c2, f2 = go(t[1])
        return r1, c2, f1 + f2 + 2 * r1 * c1 * c2
    return go(order)[2]

def best_chain_cost(dims):
    n = len(dims) - 1
    cost = [[0] * n for _ in range(n)]
    split = [[0] * n for _ in range(n)]
    for L in range(2, n + 1):
        for i in range(n - L + 1):
            j = i + L - 1
            cost[i][j] = float("inf")
            for s in range(i, j):
                c = (cost[i][s] + cost[s + 1][j]
                     + 2 * dims[i] * dims[s + 1] * dims[j + 1])
                if c < cost[i][j]:
                    cost[i][j], split[i][j] = c, s
    return cost[0][n - 1], split

import numpy as np

def log_sigmoid(x):
    return -np.logaddexp(0.0, -x)

def dpo_loss(pi_w, pi_l, ref_w, ref_l, beta=0.1):
    # inputs: summed token log-probs of each full response
    m = beta * ((pi_w - ref_w) - (pi_l - ref_l))
    loss = -log_sigmoid(m).mean()
    g = -beta * np.exp(log_sigmoid(-m)) / len(m)
    return loss, g, -g       # loss, dL/dpi_w, dL/dpi_l

