def rayleigh(A, v):
    return v @ A @ v / (v @ v)

def power_iteration(A, iters, seed=0):
    v = np.random.default_rng(seed).normal(size=A.shape[0])
    v = v / np.linalg.norm(v)
    for _ in range(iters):
        v = A @ v
        v = v / np.linalg.norm(v)
    return rayleigh(A, v), v

