def group_rates(y_true, y_pred, group):
    out = {}
    for g in sorted(set(group)):
        m = group == g
        yt, yp = y_true[m], y_pred[m]
        out[g] = {"sel": yp.mean(),
                  "tpr": yp[yt == 1].mean(),
                  "fpr": yp[yt == 0].mean()}
    return out

def spread(rates, key):
    v = [r[key] for r in rates.values()]
    return max(v) - min(v)

