    return spread(group_rates(y_true, y_pred, group), "tpr")

def equalized_odds_diff(y_true, y_pred, group):
    r = group_rates(y_true, y_pred, group)
    return max(spread(r, "tpr"), spread(r, "fpr"))

def disparate_impact(y_true, y_pred, group):
    r = group_rates(y_true, y_pred, group)
    s = [v["sel"] for v in r.values()]
    return min(s) / max(s)

