def target_encode_oof(cat, y, n_folds, smoothing, seed):
    cat, y = np.asarray(cat), np.asarray(y, float)
    rng = np.random.default_rng(seed)
    folds = rng.integers(0, n_folds, len(y))
    out = np.empty(len(y))
    for f in range(n_folds):
        tr, te = folds != f, folds == f
        prior = y[tr].mean()
        s, n = {}, {}
        for c, v in zip(cat[tr], y[tr]):
            s[c] = s.get(c, 0.0) + v
            n[c] = n.get(c, 0) + 1
        for i in np.nonzero(te)[0]:
            c = cat[i]
            num = s.get(c, 0.0) + smoothing * prior
            out[i] = num / (n.get(c, 0) + smoothing)
    return out

