    return hashlib.md5(normalise(text).encode()).hexdigest()

def shingle_set(text, k=3):
    w = normalise(text).split()
    n = max(1, len(w) - k + 1)
    return {" ".join(w[i:i + k]) for i in range(n)}

def minhash_signature(shingles, num_perm=128, seed=0):
    rng = np.random.default_rng(seed)
    a = rng.integers(1, P, num_perm)
    b = rng.integers(0, P, num_perm)
    h = lambda s: int(hashlib.md5(s.encode()).hexdigest()[:8], 16) % P
    x = np.array([h(s) for s in shingles], dtype=np.int64)
    return ((a[:, None] * x + b[:, None]) % P).min(axis=1)

def estimate_jaccard(sig_a, sig_b):
