def group_split(items, group_key, val_fraction=0.2, seed=0):
    size = Counter(group_key(x) for x in items)
    groups = sorted(size)
    np.random.default_rng(seed).shuffle(groups)
    val_g, n = set(), 0
    for g in groups:
        if n >= val_fraction * len(items):
            break
        val_g.add(g)
        n += size[g]
    val = [x for x in items if group_key(x) in val_g]
    train = [x for x in items if group_key(x) not in val_g]
    return train, val

def ngram_overlap(train, eval_texts, n=8):
    def grams(t):
        w = normalise(t).split()
        return {tuple(w[i:i + n]) for i in range(len(w) - n + 1)}
    seen = set().union(*(grams(t) for t in train))
    out = []
    for t in eval_texts:
        g = grams(t)
        out.append(len(g & seen) / len(g) if g else 0.0)
    return out

