def win_rate(outcomes):
    # outcomes: +1 win, 0 tie, -1 loss (fine-tune vs baseline)
    o = np.asarray(outcomes)
    w, l = int((o > 0).sum()), int((o < 0).sum())
    t = len(o) - w - l
