import hashlib

def hash_object(kind, data):
    header = b"%s %d\0" % (kind.encode(), len(data))
    return hashlib.sha1(header + data).hexdigest()

def tree_hash(entries):
    def order(e):
        mode, name, _ = e
        return name.encode() + (b"/" if mode == "40000" else b"")
    body = b""
    for mode, name, oid in sorted(entries, key=order):
        body += mode.encode() + b" " + name.encode() + b"\0"
        body += bytes.fromhex(oid)
    return hash_object("tree", body)

