def weight(X, xmax=100.0, alpha=0.75):
    return np.minimum(1.0, (X / xmax) ** alpha)

def residual(P, X):
    W, Wt, b, bt = P
    return W @ Wt.T + b[:, None] + bt[None, :] - np.log(X)

def loss(P, X):
    return np.sum(weight(X) * residual(P, X) ** 2)

def grads(P, X):
    W, Wt, b, bt = P
    G = 2 * weight(X) * residual(P, X)
    return [G @ Wt, G.T @ W, G.sum(axis=1), G.sum(axis=0)]

def step(P, X, lr=0.01):
    return [p - lr * g for p, g in zip(P, grads(P, X))]

