import httpx

def backoff_delay(attempt, base, cap, rng):
    return rng.uniform(0, min(cap, base * 2 ** attempt))

def is_retryable(status):
    return status == 429 or 500 <= status < 600

def call_with_retries(send, max_tries, sleep, rng,
                      base=0.5, cap=8.0):
    for attempt in range(max_tries):
        try:
            r = send()
            if not is_retryable(r.status_code):
                return r
            wait = backoff_delay(attempt, base, cap, rng)
            ra = r.headers.get("Retry-After", "")
            if ra.isdigit():
                wait = max(wait, float(ra))
        except httpx.TimeoutException:
            wait = backoff_delay(attempt, base, cap, rng)
        if attempt < max_tries - 1:
            sleep(wait)
    raise RuntimeError(f"gave up after {max_tries} tries")

