def iou(a, b):
    lo, hi = np.maximum(a[:2], b[:2]), np.minimum(a[2:], b[2:])
    inter = np.prod(np.clip(hi - lo, 0, None))
    area = lambda r: (r[2] - r[0]) * (r[3] - r[1])
    return inter / (area(a) + area(b) - inter)

def average_precision(dets, gts, thr=0.5):
    # dets: [(img, score, box)], gts: {img: [box, ...]}, one class
    dets = sorted(dets, key=lambda d: -d[1])
    used = {i: np.zeros(len(g), bool) for i, g in gts.items()}
    n_gt = sum(len(g) for g in gts.values())
    tp = np.zeros(len(dets))
    for k, (img, _, box) in enumerate(dets):
        ious = np.array([iou(box, g) for g in gts.get(img, [])])
        if len(ious):
            ious[used[img]] = -1
            j = ious.argmax()
            if ious[j] >= thr:
                used[img][j], tp[k] = True, 1
    tp_c, fp_c = np.cumsum(tp), np.cumsum(1 - tp)
    rec, prec = tp_c / n_gt, tp_c / (tp_c + fp_c)
    prec = np.maximum.accumulate(prec[::-1])[::-1]
    return float(np.sum(np.diff(np.r_[0, rec]) * prec))

