    aps = [average_precision(dets_by_cls.get(c, []), g, thr)
           for c, g in gts_by_cls.items()]
    return float(np.mean(aps))

import math

class Value:
    def __init__(self, data, parents=()):
        self.data, self.grad = data, 0.0
        self.parents, self._back = parents, lambda: None

    def __add__(self, o):
        o = o if isinstance(o, Value) else Value(o)
        out = Value(self.data + o.data, (self, o))
        def back():
            self.grad += out.grad
            o.grad += out.grad
        out._back = back
        return out

    def __mul__(self, o):
        o = o if isinstance(o, Value) else Value(o)
        out = Value(self.data * o.data, (self, o))
        def back():
            self.grad += o.data * out.grad
            o.grad += self.data * out.grad
        out._back = back
        return out

    def __pow__(self, p):  # constant exponent
        out = Value(self.data ** p, (self,))
        def back():
            self.grad += p * self.data ** (p - 1) * out.grad
        out._back = back
        return out

    def tanh(self):
        out = Value(math.tanh(self.data), (self,))
        def back():
            self.grad += (1 - out.data ** 2) * out.grad
        out._back = back
        return out

    def relu(self):
        out = Value(max(0.0, self.data), (self,))
        def back():
            self.grad += (out.data > 0) * out.grad
        out._back = back
        return out

    def exp(self):
        out = Value(math.exp(self.data), (self,))
        def back():
            self.grad += out.data * out.grad
        out._back = back
        return out

    __radd__, __rmul__ = __add__, __mul__
    def __neg__(self): return self * -1
    def __sub__(self, o): return self + (-o)

    def backward(self):
        order, seen = [], set()
        def visit(v):
            if v not in seen:
                seen.add(v)
                for p in v.parents:
                    visit(p)
                order.append(v)
        visit(self)
        self.grad = 1.0
        for v in reversed(order):
            v._back()

import numpy as np

def softmax(s):
    e = np.exp(s - s.max(-1, keepdims=True))
    return e / e.sum(-1, keepdims=True)

def top_k_gate(logits, k):
    idx = np.argsort(-logits, axis=-1)[:, :k]
    gates = softmax(np.take_along_axis(logits, idx, axis=-1))
    return idx, gates

def expert(x, W1, W2):
    return np.maximum(x @ W1, 0) @ W2

def moe_layer(x, Wr, experts, k):
    idx, gates = top_k_gate(x @ Wr, k)
    out = np.zeros_like(x)
    for t in range(len(x)):
        for j in range(k):
            W1, W2 = experts[idx[t, j]]
            out[t] += gates[t, j] * expert(x[t], W1, W2)
    return out

def balance_loss(logits, k):
    T, E = logits.shape
    idx, _ = top_k_gate(logits, k)
    f = np.bincount(idx.ravel(), minlength=E) / (T * k)
    P = softmax(logits).mean(0)
    return E * np.sum(f * P)

