            and c["memory_gb"] <= req["max_memory_gb"])

def rank(req, cands):
    ok = {n: c for n, c in cands.items() if feasible(req, c)}
    if not ok:
        return []
    n_in, n_out = req["tokens"]
    cost = {n: request_cost(n_in, n_out, c["p_in"], c["p_out"])
            for n, c in ok.items()}
    best_c = min(cost.values())
    best_l = min(c["latency"] for c in ok.values())
    w = req["weights"]
    tot = sum(w.values())
    u = {n: (w["quality"] * c["quality"]
             + w["cost"] * best_c / cost[n]
             + w["speed"] * best_l / c["latency"]) / tot
         for n, c in ok.items()}
    return sorted(u.items(), key=lambda kv: -kv[1])

