def multi_head_attention(X, Wq, Wk, Wv, Wo, h):
    T, d = X.shape
    dh = d // h
    def split(M):
        return (X @ M).reshape(T, h, dh).transpose(1, 0, 2)
    Q, K, V = split(Wq), split(Wk), split(Wv)
    A = softmax(Q @ K.transpose(0, 2, 1) / np.sqrt(dh))
    heads = A @ V
    return heads.transpose(1, 0, 2).reshape(T, d) @ Wo, A

