def groupby_agg(keys, values, fn):
    groups = {}
    for k, v in zip(keys, values):
        groups.setdefault(k, []).append(v)
    return {k: fn(vs) for k, vs in sorted(groups.items())}

def left_join(left_rows, right_rows, key):
    index = {}
    for r in right_rows:
        index.setdefault(r[key], []).append(r)
    cols = [c for c in right_rows[0] if c != key]
    miss = [dict.fromkeys(cols, np.nan)]
    out = []
    for l in left_rows:
        for r in index.get(l[key], miss):
            out.append({**l, **{c: r[c] for c in cols}})
    return out

def rolling_mean(x, w):
    x = np.asarray(x, dtype=float)
    out = np.full(len(x), np.nan)
    if len(x) >= w:
        win = np.lib.stride_tricks.sliding_window_view(x, w)
        out[w - 1:] = win.mean(axis=1)
    return out

def lag(x, k):
    x = np.asarray(x, dtype=float)
    out = np.full(len(x), np.nan)
    if k < len(x):
        out[k:] = x[:len(x) - k]
    return out

