def count_params(L, d, d_ff, V, tied=True):
    # Biases are counted; LayerNorm has gain and bias.
    attn = 4 * (d * d + d)            # Wq, Wk, Wv, Wo
    ffn = 2 * d * d_ff + d_ff + d     # up and down projections
    norms = 2 * (2 * d)               # two LayerNorms per block
    block = attn + ffn + norms
    head = 0 if tied else V * d       # separate output matrix
    return L * block + V * d + 2 * d + head

