import numpy as np

def predict(X, w, b):
    return np.where(X @ w + b > 0, 1, -1)

def perceptron_fit(X, y, epochs, eta=1.0):
    w, b, mistakes = np.zeros(X.shape[1]), 0.0, 0
    for _ in range(epochs):
        changed = 0
        for x, t in zip(X, y):
            if t * (x @ w + b) <= 0:
                w = w + eta * t * x
                b = b + eta * t
                changed += 1
        mistakes += changed
        if changed == 0:
            break
    return w, b, mistakes

def margin(X, y, w):
