import re

def luhn_valid(number):
    d = [int(c) for c in number if c.isdigit()]
    if len(d) < 13:
        return False
    tot = 0
    for i, x in enumerate(reversed(d)):
        if i % 2:
            x *= 2
            if x > 9:
                x -= 9
        tot += x
    return tot % 10 == 0

RX = [
    ("CARD", r"(?<!\d)\d(?:[ -]?\d){12,18}(?!\d)"),
    ("EMAIL", r"[\w.+-]+@[\w-]+(?:\.[\w-]+)+"),
    ("IP", r"(?<![\d.])(?:\d{1,3}\.){3}\d{1,3}(?![\d.])"),
    ("PHONE", r"(?<!\d)(?:\(\d{3}\) ?|\d{3}[-. ])\d{3}[-. ]\d{4}"
              r"(?!\d)"),
]

def ok(kind, s):
    if kind == "CARD":
        return luhn_valid(s)
    if kind == "IP":
        return all(int(x) <= 255 for x in s.split("."))
    return True

def detect(text):
    taken, out = [], []
    for kind, pat in RX:
        for m in re.finditer(pat, text):
            a, b = m.span()
            if ok(kind, m.group()) and not any(
                    a < y and x < b for x, y in taken):
                taken.append((a, b))
                out.append((kind, (a, b)))
    return sorted(out, key=lambda t: t[1])

def redact(text):
    names, count, parts, pos = {}, {}, [], 0
    for kind, (a, b) in detect(text):
        val = text[a:b].lower()
        if (kind, val) not in names:
            count[kind] = count.get(kind, 0) + 1
            names[(kind, val)] = f"<{kind}_{count[kind]}>"
        parts += [text[pos:a], names[(kind, val)]]
        pos = b
    return "".join(parts) + text[pos:]

def precision_recall(pred, true):
    pred, true = set(pred), set(true)
    tp = len(pred & true)
    p = tp / len(pred) if pred else 1.0
    r = tp / len(true) if true else 1.0
    return p, r

def gpipe_forward_schedule(p, m):
    steps = m + p - 1
    return [[t - s if 0 <= t - s < m else None
             for t in range(steps)] for s in range(p)]

def bubble_fraction(p, m):
    return (p - 1) / (m + p - 1)

def one_f_one_b(stage, p, m):
    warm = min(p - stage - 1, m)
    order = [("F", j) for j in range(warm)]
    for i in range(m - warm):
        order.append(("F", warm + i))
        order.append(("B", i))
    order += [("B", j) for j in range(m - warm, m)]
    return order

import numpy as np

def brier(y, p):
    return np.mean((p - y) ** 2)

def reliability(y, p, n_bins=10):
    edges = np.linspace(0, 1, n_bins + 1)[1:-1]
    ids = np.searchsorted(edges, p)
    n = np.bincount(ids, minlength=n_bins)
    conf = np.bincount(ids, p, n_bins)
    hit = np.bincount(ids, y, n_bins)
    keep = n > 0
    return hit[keep] / n[keep], conf[keep] / n[keep], n[keep]

def ece(y, p, n_bins=10):
    acc, conf, n = reliability(y, p, n_bins)
    return (n * np.abs(acc - conf)).sum() / n.sum()

