import re

PAT = re.compile(r"\{\{|\}\}|\{(\w+)\}")
OPEN, CLOSE = "<data>", "</data>"

def fields(t):
    return sorted({m.group(1) for m in PAT.finditer(t)
                   if m.group(1)})

def render(t, **v):
    need = set(fields(t))
    if need - v.keys():
        raise KeyError(f"missing: {sorted(need - v.keys())}")
    if v.keys() - need:
        raise KeyError(f"extra: {sorted(v.keys() - need)}")
    return PAT.sub(
        lambda m: str(v[m.group(1)]) if m.group(1)
        else m.group(0)[0], t)

def wrap(value):
    s = str(value)
    while OPEN in s or CLOSE in s:
        s = s.replace(OPEN, "").replace(CLOSE, "")
    return OPEN + s + CLOSE

def safe_render(t, untrusted=(), **v):
    v = {k: wrap(x) if k in untrusted else x
         for k, x in v.items()}
    return render(t, **v)

def count(s):
    return len(s.split())

def render_budget(t, var, limit, **v):
    room = limit - count(render(t, **{**v, var: ""}))
    if room < 0:
        raise ValueError("fixed text exceeds the budget")
    words = str(v[var]).split()[:room]
    return render(t, **{**v, var: " ".join(words)})

