import hashlib
from scipy.stats import binomtest

def normalise(t):
    lines = t.strip().splitlines()
    return "\n".join(l.rstrip() for l in lines)

def prompt_hash(template):
    data = normalise(template).encode()
    return hashlib.sha256(data).hexdigest()[:12]

class Registry:
    def __init__(self):
        self.items = {}

    def register(self, name, version, template, note=""):
        if (name, version) in self.items:
            raise ValueError("versions are immutable")
        h = prompt_hash(template)
        self.items[(name, version)] = (template, h, note)
        return h

    def get(self, name, version):
        return self.items[(name, version)][0]

    def latest(self, name):
        key = lambda v: tuple(map(int, v.split(".")))
        vs = [v for n, v in self.items if n == name]
        best = max(vs, key=key)
        return best, self.get(name, best)

def regression_gate(old_correct, new_correct, alpha=0.05):
    pairs = list(zip(old_correct, new_correct))
    b = sum(1 for o, n in pairs if n and not o)
    c = sum(1 for o, n in pairs if o and not n)
    if b + c == 0:
        return True, 1.0, b, c
    p = binomtest(c, b + c, 0.5, alternative="greater").pvalue
    return p >= alpha, p, b, c

def route_canary(user_id, fraction, salt="v2"):
    h = hashlib.sha256((salt + user_id).encode()).hexdigest()
    return "new" if int(h[:8], 16) / 2**32 < fraction else "old"

