class Pipeline:
    def __init__(self, steps, model):
        self.steps, self.model = steps, model

    def fit(self, X, y=None):
        for s in self.steps:
            X = s.fit(X, y).transform(X)
        self.model.fit(X, y)
        return self

    def predict(self, X):
        for s in self.steps:
            X = s.transform(X)
        return self.model.predict(X)

import numpy as np

def q_learning(nxt, rew, done, n_ep=3000, alpha=0.5, gamma=0.9,
               eps=0.3, seed=0):
    rng = np.random.default_rng(seed)
    S, A = nxt.shape
    Q = np.zeros((S, A))
    for _ in range(n_ep):
        s = rng.integers(S)
        for _ in range(100):
            if done[s]:
                break
            if rng.random() < eps:
                a = rng.integers(A)
            else:
                a = Q[s].argmax()
            s2 = nxt[s, a]
            target = rew[s, a] + gamma * Q[s2].max()
            Q[s, a] += alpha * (target - Q[s, a])
            s = s2
    return Q

import numpy as np
from scipy.stats import norm

def make_nf4_levels(offset=0.9677083):
    pos = norm.ppf(np.linspace(offset, 0.5, 9)[:-1])
    neg = -norm.ppf(np.linspace(offset, 0.5, 8)[:-1])
    lv = np.sort(np.concatenate([pos, [0.0], neg]))
    return lv / np.abs(lv).max()

def quantize_blockwise(w, block=64, levels=None):
    lv = make_nf4_levels() if levels is None else levels
    b = w.reshape(-1, block)
    s = np.abs(b).max(axis=1, keepdims=True)
    s = np.where(s == 0, 1.0, s)
    idx = np.abs(b[..., None] / s[..., None] - lv).argmin(-1)
    return idx.astype(np.uint8), s

def dequantize(idx, s, levels=None):
    lv = make_nf4_levels() if levels is None else levels
    return (lv[idx] * s).ravel()

def bytes_per_param(block=64, double_quant=True):
    if double_quant:
        scale_bits = 8 / block + 32 / (block * 256)
    else:
        scale_bits = 32 / block
    return (4 + scale_bits) / 8

import numpy as np, zlib

def embed(text, dim=256, seed=0):
    v = np.zeros(dim)
    for w in text.lower().split():
        h = zlib.crc32(f"{seed}:{w}".encode())
        v[h % dim] += 1 if (h >> 16) & 1 else -1
    n = np.linalg.norm(v)
    return v / n if n else v

def top_k(v, corpus_vecs, k):
    order = np.argsort(-(corpus_vecs @ v), kind="stable")
    return [int(i) for i in order[:k]]

def hyde_retrieve(query, corpus_vecs, generator, k):
    return top_k(embed(generator(query)), corpus_vecs, k)

def rrf(rankings, rrf_k=60):
    s = {}
    for r in rankings:
        for pos, d in enumerate(r, start=1):
            s[d] = s.get(d, 0.0) + 1.0 / (rrf_k + pos)
    return sorted(s.items(), key=lambda t: -t[1])

def multi_query_retrieve(queries, corpus_vecs, k, rrf_k=60):
    lists = [top_k(embed(q), corpus_vecs, k) for q in queries]
    return rrf(lists, rrf_k)[:k]

