import numpy as np

def context_precision(ranked_relevance):
    rel = np.asarray(ranked_relevance, float)
    if rel.sum() == 0:
        return 0.0
    prec_at_k = np.cumsum(rel) / np.arange(1, len(rel) + 1)
    return float((prec_at_k * rel).sum() / rel.sum())

def toks(s):
    return set(re.findall(r"[a-z0-9]+", s.lower()))

def context_recall(needed_facts, retrieved_text):
    text = retrieved_text.lower()
    hit = [f.lower() in text for f in needed_facts]
    return sum(hit) / len(hit)

def overlap_support(claim, context, thr=0.8):
    c = toks(claim)
    return bool(c) and len(c & toks(context)) / len(c) >= thr

def faithfulness(claims, context, support_fn=overlap_support):
    ok = [support_fn(c, context) for c in claims]
    return sum(ok) / len(ok)

def answer_relevance(question, answer):
    stop = {"the", "a", "of", "is", "what", "in", "to", "and"}
    q = toks(question) - stop
    return len(q & toks(answer)) / len(q)

def rag_report(ranked_rel, facts, ctx, claims, q, ans):
    return {"context_precision": context_precision(ranked_rel),
            "context_recall": context_recall(facts, ctx),
            "faithfulness": faithfulness(claims, ctx),
            "answer_relevance": answer_relevance(q, ans)}

import numpy as np

def gini(y):
    p = np.bincount(y, minlength=2) / len(y)
    return 1 - p @ p

def grow(X, y, depth, m, rng):
    leaf = np.bincount(y, minlength=2).argmax()
    if depth == 0 or gini(y) == 0:
        return leaf
    best = (gini(y), None, None)
    for j in rng.choice(X.shape[1], m, replace=False):
        for t in np.unique(X[:, j])[:-1]:
            k = X[:, j] <= t
            s = k.mean() * gini(y[k]) + (1 - k.mean()) * gini(y[~k])
            if s < best[0]:
                best = (s, j, t)
    if best[1] is None:
        return leaf
    _, j, t = best
    k = X[:, j] <= t
    l = grow(X[k], y[k], depth - 1, m, rng)
    return (j, t, l, grow(X[~k], y[~k], depth - 1, m, rng))

def fit(X, y, B=25, depth=6, seed=0):
    rng = np.random.default_rng(seed)
    m = max(1, int(np.sqrt(X.shape[1])))
    trees = []
    for _ in range(B):
        i = rng.integers(0, len(X), len(X))
        trees.append(grow(X[i], y[i], depth, m, rng))
    return trees

def predict_one(trees, x):
    votes = []
    for tree in trees:
        while isinstance(tree, tuple):
            j, t, l, r = tree
            tree = l if x[j] <= t else r
        votes.append(tree)
    return int(np.mean(votes) > 0.5)

def receptive_field(layers):
    rf, jump = 1, 1
    for k, s in layers:
        rf += (k - 1) * jump
        jump *= s
    return rf, jump

def input_span(layers, i):
    lo, hi = i, i
    for k, s in reversed(layers):
        lo = lo * s
        hi = hi * s + k - 1
    return lo, hi

import numpy as np

def mmr(q, D, k, lam):
    rel = D @ q
    sel, rest = [], list(range(len(D)))
    while rest and len(sel) < k:
        def score(i):
            red = max((D[i] @ D[j] for j in sel), default=0.0)
            return lam * rel[i] - (1 - lam) * red
        best = max(rest, key=score)
        sel.append(best)
        rest.remove(best)
    return sel

def rerank(candidates, score_fn, top_n):
    ranked = sorted(candidates, key=score_fn, reverse=True)
    return ranked[:top_n]

def diversity(D, idx):
    S = D[idx] @ D[idx].T
    n = len(idx)
    return (S.sum() - n) / (n * (n - 1))

