import numpy as np

def conv(x, w, stride=1, pad=1):
    x = np.pad(x, ((0, 0), (0, 0), (pad, pad), (pad, pad)))
    k = w.shape[2]
    oh = (x.shape[2] - k) // stride + 1
    ow = (x.shape[3] - k) // stride + 1
    out = np.zeros((x.shape[0], w.shape[0], oh, ow))
    for i in range(oh):
        for j in range(ow):
            r, s = i * stride, j * stride
            p = x[:, :, r:r + k, s:s + k]
            out[:, :, i, j] = np.einsum("ncuv,fcuv->nf", p, w)
    return out

def bn(x, g, b, eps=1e-5):
    mu = x.mean(axis=(0, 2, 3), keepdims=True)
    var = x.var(axis=(0, 2, 3), keepdims=True)
    xhat = (x - mu) / np.sqrt(var + eps)
    return g.reshape(1, -1, 1, 1) * xhat + b.reshape(1, -1, 1, 1)

def basic_block(x, p, stride=1):
    out = bn(conv(x, p["w1"], stride), p["g1"], p["b1"])
    out = bn(conv(np.maximum(0, out), p["w2"]), p["g2"], p["b2"])
    if "ws" in p:
        x = bn(conv(x, p["ws"], stride, 0), p["gs"], p["bs"])
    return np.maximum(0, out + x)

import numpy as np

def ranked_rel(scores, rel):
    order = np.argsort(-scores, axis=1)
    return np.take_along_axis(rel, order, axis=1)

def recall_at_k(scores, rel, k):
    hit = ranked_rel(scores, rel) > 0
    return np.mean(hit[:, :k].sum(1) / hit.sum(1))

def mrr(scores, rel):
    hit = ranked_rel(scores, rel) > 0
    return np.mean(1.0 / (hit.argmax(1) + 1))

def ndcg_at_k(scores, rel, k):
    disc = 1 / np.log2(np.arange(2, k + 2))
    dcg = (ranked_rel(scores, rel)[:, :k] * disc).sum(1)
    ideal = (-np.sort(-rel, axis=1)[:, :k] * disc).sum(1)
    return np.mean(dcg / ideal)

import numpy as np

def ridge(X, y, lam):
    xm, ym = X.mean(0), y.mean()
    Xc = X - xm
    A = Xc.T @ Xc + lam * np.eye(X.shape[1])
    w = np.linalg.solve(A, Xc.T @ (y - ym))
    return w, ym - xm @ w

def soft(z, t):
    return np.sign(z) * np.maximum(np.abs(z) - t, 0)

def lasso(X, y, lam, sweeps=500):
    xm, ym = X.mean(0), y.mean()
    Xc, r = X - xm, y - ym
    w = np.zeros(X.shape[1])
    for _ in range(sweeps):
        for j in range(len(w)):
            r += Xc[:, j] * w[j]
            z = Xc[:, j] @ r / len(r)
            w[j] = soft(z, lam) / (Xc[:, j] ** 2).mean()
            r -= Xc[:, j] * w[j]
    return w, ym - xm @ w

import numpy as np

def adagrad_step(w, g, G, lr=0.1, eps=1e-10):
    G = G + g * g
    return w - lr * g / (np.sqrt(G) + eps), G

def rmsprop_step(w, g, v, lr=0.01, alpha=0.99, eps=1e-8):
    v = alpha * v + (1 - alpha) * g * g
    return w - lr * g / (np.sqrt(v) + eps), v

def minimize(step, grad, w, n=50, **kw):
    state = np.zeros_like(w)
    for _ in range(n):
        w, state = step(w, grad(w), state, **kw)
    return w

import numpy as np

def rnn_cell(x, h, Wx, Wh, b):
    return np.tanh(x @ Wx.T + h @ Wh.T + b)

def rnn_forward(X, h0, Wx, Wh, b):
    h, out = h0, []
    for x in X:
        h = rnn_cell(x, h, Wx, Wh, b)
        out.append(h)
    return np.stack(out), h

import re

END = "<|end|>\n"

def render_chat(messages, gen_prompt=True):
    s = "".join(f"<|{m['role']}|>\n{m['content']}\n{END}"
                for m in messages)
    return s + ("<|assistant|>\n" if gen_prompt else "")

def validate_messages(msgs):
    if not msgs or msgs[0]["role"] != "system":
        raise ValueError("first message must be system")
    nxt = {"system": {"user"}, "user": {"assistant"},
           "assistant": {"user", "tool"},
           "tool": {"tool", "assistant"}}
    for a, b in zip(msgs, msgs[1:]):
        if b["role"] not in nxt[a["role"]]:
            raise ValueError(f"{a['role']} -> {b['role']}")

def trim_messages(msgs, budget, count):
    cost = lambda m: count(render_chat([m], False))
    left = budget - cost(msgs[0])
    if left < 0:
        raise ValueError("system message exceeds budget")
    keep = []
    for m in reversed(msgs[1:]):
        if cost(m) > left:
            break
        keep.append(m)
        left -= cost(m)
    keep.reverse()
    while keep and keep[0]["role"] != "user":
        keep.pop(0)
    return [msgs[0]] + keep

def parse_chat(text):
    pat = r"<\|(\w+)\|>\n(.*?)\n<\|end\|>\n"
    return [{"role": r, "content": c}
            for r, c in re.findall(pat, text, re.S)]

import numpy as np
from collections import Counter

def ngrams(t, n):
    return Counter(zip(*[t[i:] for i in range(n)]))

def prf(ov, n_hyp, n_ref):
    p = ov / n_hyp if n_hyp else 0.0
    r = ov / n_ref if n_ref else 0.0
    return p, r, 2 * p * r / (p + r) if p + r else 0.0

def rouge_n(hyp, ref, n=1):
    h, r = ngrams(hyp, n), ngrams(ref, n)
    ov = sum((h & r).values())
    return prf(ov, sum(h.values()), sum(r.values()))

def lcs_len(a, b):
    L = np.zeros((len(a) + 1, len(b) + 1), dtype=int)
    for i, x in enumerate(a, 1):
        for j, y in enumerate(b, 1):
            L[i, j] = (L[i-1, j-1] + 1 if x == y
                       else max(L[i-1, j], L[i, j-1]))
    return L[-1, -1]

def rouge_l(hyp, ref):
    return prf(lcs_len(hyp, ref), len(hyp), len(ref))

import numpy as np

def softmax(s):
    e = np.exp(s - s.max(axis=-1, keepdims=True))
    return e / e.sum(axis=-1, keepdims=True)

def self_attention(X, Wq, Wk, Wv, causal=False):
    Q, K, V = X @ Wq, X @ Wk, X @ Wv
    scores = Q @ K.T / np.sqrt(K.shape[-1])
    if causal:
        keep = np.tril(np.ones(scores.shape, dtype=bool))
        scores = np.where(keep, scores, -np.inf)
    A = softmax(scores)
    return A @ V, A

import numpy as np

def viterbi_segment(word, logp):
    n = len(word)
    best = [0.0] + [-np.inf] * n
    back = [0] * (n + 1)
    for j in range(1, n + 1):
        for i in range(j):
            s = word[i:j]
            if s in logp and best[i] + logp[s] > best[j]:
                best[j] = best[i] + logp[s]
                back[j] = i
    if best[n] == -np.inf:
        return None, best[n]
    out, j = [], n
    while j > 0:
        out.append(word[back[j]:j])
        j = back[j]
    return out[::-1], best[n]

def lattice(word, p):
    n = len(word)
    a = [1.0] + [0.0] * n
    b = [0.0] * n + [1.0]
    for j in range(1, n + 1):
        for i in range(j):
            a[j] += a[i] * p.get(word[i:j], 0.0)
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n + 1):
            b[i] += p.get(word[i:j], 0.0) * b[j]
    return a, b

def em_step(freqs, p):
    cnt = dict.fromkeys(p, 0.0)
    ll = 0.0
    for w, f in freqs.items():
        a, b = lattice(w, p)
        ll += f * np.log(a[-1])
        for i in range(len(w)):
            for j in range(i + 1, len(w) + 1):
                s = w[i:j]
                if s in p:
                    cnt[s] += f * a[i] * p[s] * b[j] / a[-1]
    tot = sum(cnt.values())
    return {s: c / tot for s, c in cnt.items()}, ll

import copy
import numpy as np

class FitTransform:
    def fit_transform(self, X, y=None):
        return self.fit(X, y).transform(X)

class StandardScaler(FitTransform):
    def fit(self, X, y=None):
        X = np.asarray(X, float)
        self.mean_, self.std_ = X.mean(0), X.std(0)
        return self

    def transform(self, X):
        X = np.asarray(X, float)
        return (X - self.mean_) / self.std_

class OneHot(FitTransform):
    def fit(self, X, y=None):
        self.cats_ = [np.unique(c) for c in X.T]
        return self

    def transform(self, X):
        return np.hstack([(c[:, None] == u).astype(float)
                          for c, u in zip(X.T, self.cats_)])

class ColumnTransformer(FitTransform):
    def __init__(self, parts):
        self.parts = parts  # list of (transformer, columns)

    def fit(self, X, y=None):
        self.fitted_ = [(copy.deepcopy(t).fit(X[:, c]), c)
                        for t, c in self.parts]
        return self

    def transform(self, X):
        return np.hstack([t.transform(X[:, c])
                          for t, c in self.fitted_])

class Pipeline:
    def __init__(self, steps):
        self.steps = steps

    def fit(self, X, y):
        self.fitted_ = [copy.deepcopy(s) for s in self.steps]
        for s in self.fitted_[:-1]:
            X = s.fit_transform(X)
        self.fitted_[-1].fit(X, y)
        return self

    def predict(self, X):
        for s in self.fitted_[:-1]:
            X = s.transform(X)
        return self.fitted_[-1].predict(X)

class LinearReg:
    def fit(self, X, y):
        xm, ym = X.mean(0), y.mean()
        A, t = X - xm, y - ym
        self.coef_ = np.linalg.lstsq(A, t, rcond=None)[0]
        self.b_ = ym - xm @ self.coef_
        return self

    def predict(self, X):
        return X @ self.coef_ + self.b_

import numpy as np

def band_mask(T, W):
    i = np.arange(T)[:, None]
    j = np.arange(T)[None, :]
    return (j <= i) & (j > i - W)

def window_attn(q, k, v, W):
    T = len(q)
    s = q @ k.T / np.sqrt(q.shape[1])
    s = np.where(band_mask(T, W), s, -np.inf)
    e = np.exp(s - s.max(-1, keepdims=True))
    return (e / e.sum(-1, keepdims=True)) @ v

def ring_update(K, V, k, v, pos):
    K[pos % len(K)], V[pos % len(V)] = k, v

