import numpy as np

def accept_or_resample(p, q, x, rng):
    if rng.random() < min(1.0, p[x] / q[x]):
        return x, True
    r = np.maximum(p - q, 0.0)
    return rng.choice(len(p), p=r / r.sum()), False

def speculative_step(p_fn, q_fn, prefix, gamma, rng):
    seq, draft = list(prefix), []
    for _ in range(gamma):
        q = q_fn(seq)
        x = rng.choice(len(q), p=q)
        draft.append((x, q))
        seq.append(x)
    out = []
    for x, q in draft:
        p = p_fn(list(prefix) + out)
        t, ok = accept_or_resample(p, q, x, rng)
        out.append(t)
        if not ok:
            return out
    p = p_fn(list(prefix) + out)
    return out + [rng.choice(len(p), p=p)]

def expected_tokens(alpha, gamma):
    if alpha >= 1.0:
        return gamma + 1.0
    return (1 - alpha ** (gamma + 1)) / (1 - alpha)

import json
import numpy as np
from jsonschema import Draft202012Validator

def extract_json(text):
    start = text.find("{")
    while start != -1:
        depth, in_str, esc = 0, False, False
        for i in range(start, len(text)):
            c = text[i]
            if in_str:
                if esc:
                    esc = False
                elif c == "\\":
                    esc = True
                elif c == '"':
                    in_str = False
            elif c == '"':
                in_str = True
            elif c == "{":
                depth += 1
            elif c == "}":
                depth -= 1
                if depth == 0:
                    try:
                        return json.loads(text[start:i + 1])
                    except ValueError:
                        break
        start = text.find("{", start + 1)
    return None

def validate(obj, schema):
    v = Draft202012Validator(schema)
    return sorted(e.message for e in v.iter_errors(obj))

def retry(generate, prompt, schema, max_tries=3):
    p = prompt
    for attempt in range(max_tries):
        obj = extract_json(generate(p, attempt))
        errs = (["no JSON object found"] if obj is None
                else validate(obj, schema))
        if not errs:
            return obj, attempt + 1
        p = (prompt + "\nInvalid reply: " + "; ".join(errs)
             + "\nReturn only the fixed JSON.")
    return None, max_tries

def masked_softmax(logits, allowed):
    z = np.where(allowed, logits, -np.inf)
    e = np.exp(z - z.max())
    return e / e.sum()

VOCAB = ["{", '"a"', ":", "1", "2", "}", "hi"]
ALLOWED = [[0], [1], [2], [3, 4], [5]]  # tokens legal per state

def constrained_decode(logits_per_step):
    out = []
    for state, logits in enumerate(logits_per_step):
        ok = np.zeros(len(VOCAB), bool)
        ok[ALLOWED[state]] = True
        p = masked_softmax(logits, ok)
        out.append(VOCAB[int(p.argmax())])
    return "".join(out)

import numpy as np

def svd(A):
    w, V = np.linalg.eigh(A.T @ A)
    idx = np.argsort(w)[::-1]
    s = np.sqrt(np.clip(w[idx], 0, None))
    V = V[:, idx]
    U = A @ V / np.where(s > 1e-12, s, 1.0)
    return U, s, V.T

def low_rank(U, s, Vt, k):
    return (U[:, :k] * s[:k]) @ Vt[:k]

def rank_error(s, k):
