import numpy as np

def fit(X, y, lam=0.01, iters=3000):
    # y must be in {-1, +1}
    w, b = np.zeros(X.shape[1]), 0.0
    for t in range(1, iters + 1):
        bad = y * (X @ w + b) < 1
        gw = lam * w - (y[bad, None] * X[bad]).sum(0) / len(y)
        gb = -y[bad].sum() / len(y)
        eta = 1 / (lam * (t + 10))
        w -= eta * gw
        b -= eta * gb
    return w, b

def predict(w, b, X):
    return np.sign(X @ w + b)

def corrupt_spans(tokens, spans):
    inp, tgt, pos = [], [], 0
    for i, (s, n) in enumerate(spans):
        sent = f"<extra_id_{i}>"
        inp += tokens[pos:s] + [sent]
        tgt += [sent] + tokens[s:s + n]
        pos = s + n
    inp += tokens[pos:]
    return inp, tgt + ["</s>"]

def reconstruct(inp, tgt):
    spans, cur = {}, None
    for t in tgt[:-1]:
        if t.startswith("<extra_id_"):
            cur = t
            spans[cur] = []
        else:
            spans[cur].append(t)
    out = []
    for t in inp:
        out += spans.get(t, [t])
    return out

