import numpy as np

def gelu(x):
    c = np.sqrt(2 / np.pi)
    return 0.5 * x * (1 + np.tanh(c * (x + 0.044715 * x**3)))

def column_split(W, n):
    return np.split(W, n, axis=1)

def row_split(W, n):
    return np.split(W, n, axis=0)

def all_reduce_sum(parts):
    total = parts[0]
    for p in parts[1:]:
        total = total + p
    return total

def tp_mlp(x, W1, W2, n_devices):
    A = column_split(W1, n_devices)
    B = row_split(W2, n_devices)
    parts = [gelu(x @ a) @ b for a, b in zip(A, B)]
    return all_reduce_sum(parts)

