import re

STOP = {"the", "a", "an", "is", "are", "and", "of", "to", "over"}
LEMMA = {"ran": "run", "mice": "mouse", "better": "good"}

def normalise(text):
    return re.findall(r"[a-z0-9]+", text.lower())

def has_vowel(s):
    return re.search(r"[aeiou]", s) is not None

def stem(w):
    for suf, rep in [("sses", "ss"), ("ies", "i"), ("ss", "ss"),
                     ("s", "")]:
        if w.endswith(suf):
            w = w[:-len(suf)] + rep
            break
    for suf in ("ing", "ed"):
        if w.endswith(suf) and has_vowel(w[:-len(suf)]):
            w = w[:-len(suf)]
            if w.endswith(("at", "bl", "iz")):
                w += "e"
            elif len(w) > 1 and w[-1] == w[-2] and w[-1] not in "lsz":
                w = w[:-1]
            break
    if w.endswith("y") and has_vowel(w[:-1]):
        w = w[:-1] + "i"
    return w

def lemmatise(w):
    return LEMMA.get(w, w)

def pipeline(text, use_stem=True):
    toks = [t for t in normalise(text) if t not in STOP]
    return [stem(t) if use_stem else lemmatise(t) for t in toks]

import numpy as np

def tfidf(docs):
    vocab = sorted({w for d in docs for w in d.split()})
    ix = {w: i for i, w in enumerate(vocab)}
    tf = np.zeros((len(docs), len(vocab)))
    for r, d in enumerate(docs):
        for w in d.split():
            tf[r, ix[w]] += 1
    df = (tf > 0).sum(0)
    idf = np.log((1 + len(docs)) / (1 + df)) + 1
    x = tf * idf
    return x / np.linalg.norm(x, axis=1, keepdims=True), vocab

import numpy as np

def softmax(z):
    e = np.exp(z - z.max())
    return e / e.sum()

def filter_logits(logits, top_k=0, top_p=1.0):
    z = logits.astype(float).copy()
    order = np.argsort(-z, kind="stable")
    if top_k > 0:
        z[order[top_k:]] = -np.inf
    p = softmax(z)[order]
    drop = np.cumsum(p) - p >= top_p
    z[order[drop]] = -np.inf
    return z

def sample(logits, rng, temperature=1.0, **kw):
    z = filter_logits(logits / temperature, **kw)
    return rng.choice(len(z), p=softmax(z))

import zlib

class Tracer:
    def __init__(self, clock, trace_id="t1"):
        self.clock, self.trace_id = clock, trace_id
        self.spans, self.stack = [], []

    def span(self, name, **attrs):
