class Span:
    def __init__(self, tracer, name, attrs):
        self.tr, self.name, self.attrs = tracer, name, attrs

    def __enter__(self):
        tr = self.tr
        self.id = len(tr.spans) + 1
        self.parent = tr.stack[-1].id if tr.stack else None
        self.start = tr.clock()
        tr.spans.append(self)
        tr.stack.append(self)
        return self

    def __exit__(self, *exc):
        self.end = self.tr.clock()
        self.tr.stack.pop()

def percentile(values, q):
