import numpy as np

def norm(x, p):
    x = np.abs(x)
    if np.isinf(p):
        return x.max()
    return (x ** p).sum() ** (1 / p)

def unit(x):
    return x / norm(x, 2)

def cosine_dist(u, v):
    return 1 - unit(u) @ unit(v)

def mahalanobis(x, y, cov):
    d = x - y
    return np.sqrt(d @ np.linalg.solve(cov, d))

import numpy as np

def patchify(img, P):
    C, H, W = img.shape
    x = img.reshape(C, H // P, P, W // P, P)
    x = x.transpose(1, 3, 0, 2, 4)      # (gh, gw, C, P, P)
    return x.reshape(-1, C * P * P)     # (N, C*P*P)

def patch_embed(img, P, W, b, cls, pos):
    tokens = patchify(img, P) @ W + b   # (N, D)
    return np.vstack([cls, tokens]) + pos

