def xavier_uniform(fan_in, fan_out, rng, gain=1.0):
    a = gain * np.sqrt(6 / (fan_in + fan_out))
    return rng.uniform(-a, a, size=(fan_out, fan_in))

def he_normal(fan_in, fan_out, rng):
    std = np.sqrt(2 / fan_in)
    return rng.normal(0, std, size=(fan_out, fan_in))

def signal_rms(init, act, width, depth, rng):
    x = rng.normal(size=(512, width))
    for _ in range(depth):
        x = act(x @ init(width, width, rng).T)
    return np.sqrt((x ** 2).mean())

