def sg_loss_grads(W, U, c, o):
    v = W[c]
    s = U @ v
    s = s - s.max()
    p = np.exp(s) / np.exp(s).sum()
    loss = -np.log(p[o])
    p[o] -= 1
    return loss, U.T @ p, np.outer(p, v)

from collections import Counter

def wordpiece_tokenize(word, vocab):
    out, start = [], 0
    while start < len(word):
        end = len(word)
        while end > start:
            s = word[start:end]
            if start > 0:
                s = "##" + s
            if s in vocab:
                break
            end -= 1
        if end == start:
            return ["[UNK]"]
        out.append(s)
        start = end
    return out

def split_word(w):
    return [w[0]] + ["##" + c for c in w[1:]]

def pair_stats(splits, freqs):
    one, two = Counter(), Counter()
    for w, toks in splits.items():
        for t in toks:
            one[t] += freqs[w]
        for p in zip(toks, toks[1:]):
            two[p] += freqs[w]
    return one, two

def best_pair(splits, freqs, use_score=True):
    one, two = pair_stats(splits, freqs)
    if not use_score:
        return max(two, key=two.get)
    return max(two, key=lambda p:
               two[p] / (one[p[0]] * one[p[1]]))

def merge(splits, pair):
    a, b = pair
    new = a + (b[2:] if b.startswith("##") else b)
    out = {}
    for w, toks in splits.items():
        r, i = [], 0
        while i < len(toks):
            if tuple(toks[i:i + 2]) == pair:
                r.append(new)
                i += 2
            else:
                r.append(toks[i])
                i += 1
        out[w] = r
    return out

